27	/**
28	 * Simple JavaBean domain object representing an owner.
29	 *
30	 * @author Ken Krebs
31	 * @author Juergen Hoeller
32	 * @author Sam Brannen
33	 * @author Michael Isvy
34	 */
35	@Entity
36	@Table(name = "owners")
37	public class Owner extends Person {
38	    @Column(name = "address")
39	    @NotEmpty
40	    private String address;
41	
42	    @Column(name = "city")
43	    @NotEmpty
44	    private String city;
45	
46	    @Column(name = "telephone")
47	    @NotEmpty
48	    @Pattern(regexp = "^\\+[0-9]{8,15}$",
49	        message = "Phone number must be in E.164 form: '+' followed by 8 to 15 digits")
50	    private String telephone;
51	
52	    @Column(name = "email")
53	    private String email;
54	
55	    @Column(name = "postcode")
56	    private String postcode;
57	
58	    @Column(name = "registration_date", columnDefinition = "DATE")
59	    private LocalDate registrationDate;
60	
61	    @Column(name = "customer_code")
62	    private String customerCode;
63	
64	    @Column(name = "namesake_count")
65	    private Integer namesakeCount;
66	
67	    @Column(name = "bulk_signup_warning")
68	    private Boolean bulkSignupWarning;
69	
70	    @Column(name = "household_size")
71	    private Integer householdSize;
72	
73	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
74	    private Set<Pet> pets;
75	
76	    public String getAddress() {
77	        return this.address;
78	    }
79	
80	    public void setAddress(String address) {
81	        this.address = address;
82	    }
83	
84	    public String getCity() {
85	        return this.city;
86	    }
87	
88	    public void setCity(String city) {
89	        this.city = city;
90	    }
91	
92	    public String getTelephone() {
93	        return this.telephone;
94	    }
95	
96	    public void setTelephone(String telephone) {
97	        this.telephone = telephone;
98	    }
99	
100	    public String getEmail() {
101	        return this.email;
102	    }
103	
104	    public void setEmail(String email) {
105	        this.email = email;
106	    }
107	
108	    public String getPostcode() {
109	        return this.postcode;
110	    }
111	
112	    public void setPostcode(String postcode) {
113	        this.postcode = postcode;
114	    }
115	
116	    public LocalDate getRegistrationDate() {
117	        return this.registrationDate;
118	    }
119	
120	    public void setRegistrationDate(LocalDate registrationDate) {
121	        this.registrationDate = registrationDate;
122	    }
123	
124	    public String getCustomerCode() {
125	        return this.customerCode;
126	    }
127	
128	    public void setCustomerCode(String customerCode) {
129	        this.customerCode = customerCode;
130	    }
131	
132	    public Integer getNamesakeCount() {
133	        return this.namesakeCount;
134	    }
135	
136	    public void setNamesakeCount(Integer namesakeCount) {
137	        this.namesakeCount = namesakeCount;
138	    }
139	
140	    public Boolean getBulkSignupWarning() {
141	        return this.bulkSignupWarning;
142	    }
143	
144	    public void setBulkSignupWarning(Boolean bulkSignupWarning) {
145	        this.bulkSignupWarning = bulkSignupWarning;
146	    }
147	
148	    public Integer getHouseholdSize() {
149	        return this.householdSize;
150	    }
151	
152	    public void setHouseholdSize(Integer householdSize) {
153	        this.householdSize = householdSize;
154	    }
155	
156	    protected Set<Pet> getPetsInternal() {
157	        if (this.pets == null) {
158	            this.pets = new HashSet<>();
159	        }
160	        return this.pets;
161	    }
162	
163	    protected void setPetsInternal(Set<Pet> pets) {
164	        this.pets = pets;
165	    }
166	
167	    public List<Pet> getPets() {
168	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
169	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
170	        return Collections.unmodifiableList(sortedPets);
171	    }
172	
173	    public void setPets(List<Pet> pets) {
174	        this.pets = new HashSet<>(pets);
175	    }
176	
177	    public void addPet(Pet pet) {
178	        getPetsInternal().add(pet);
179	        pet.setOwner(this);
180	    }
181	
182	    /**
183	     * Return the Pet with the given name, or null if none found for this Owner.
184	     *
185	     * @param name to test
186	     * @return true if pet name is already in use
187	     */
188	    public Pet getPet(String name) {
189	        return getPet(name, false);
190	    }
191	
192	    /**
193	     * Return the Pet with the given name, or null if none found for this Owner.
194	     *
195	     * @param name to test
196	     * @return true if pet name is already in use
197	     */
198	    public Pet getPet(String name, boolean ignoreNew) {
199	        name = name.toLowerCase();
200	        for (Pet pet : getPetsInternal()) {
201	            if (!ignoreNew || !pet.isNew()) {
202	                String compName = pet.getName();
203	                compName = compName.toLowerCase();
204	                if (compName.equals(name)) {
205	                    return pet;
206	                }
207	            }
208	        }
209	        return null;
210	    }
211	
212	    public Pet getPet(Integer petId) {
213	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
214	    }
