79	    private static String regionForPostcode(String postcode) {
80	        if (postcode == null || !postcode.matches("\\d{4}")) {
81	            return null;
82	        }
83	        int value = Integer.parseInt(postcode);
84	        for (java.util.Map.Entry<String, int[]> entry : REGION_POSTCODE_RANGES.entrySet()) {
85	            int[] range = entry.getValue();
