95	     * 1 when an email address is present, and gains 1 when the owner has no namesakes
96	     * (namesakeCount is 0), capped at 3. Level 4 is reserved for tenure.
97	     */
98	    default Integer membershipLevel(Owner owner) {
99	        int level = 1;
