120	        int sum = 0;
121	        boolean dbl = true;
122	        for (int i = s.length() - 1; i >= 0; i--) {
123	            char c = s.charAt(i);
124	            if (c < '0' || c > '9') {
125	                continue;
126	            }
127	            int d = c - '0';
128	            if (dbl) {
129	                d *= 2;
130	                if (d > 9) {
131	                    d -= 9;
132	                }
133	            }
134	            sum += d;
135	            dbl = !dbl;
136	        }
137	        return (10 - (sum % 10)) % 10;
